function participantList(container,engine,selectedIds){container.replaceChildren();for(const t of project.tanks){const compatible=engine==='jvm'?['java','blocks'].includes(t.language):t.language!=='java';const label=el('label','participant');const input=el('input');input.type='checkbox';input.value=t.id;input.disabled=!compatible;input.checked=compatible&&(selectedIds?selectedIds.includes(t.id):true);label.append(input,el('span','',t.name),el('small','',t.language));container.append(label);}}
function renderParticipants(){const ids=[...$('#participants').querySelectorAll('input:checked')].map(n=>n.value);participantList($('#participants'),$('#engine').value,ids.length?ids:undefined);$('#engine-info').textContent=$('#engine').value==='jvm'?'JVM Java 17 + Robocode 1.11.1. Java completo y bloques exportados a Java. Campo libre, posiciones aleatorias originales. La semilla web y los obstáculos no modifican el motor clásico.':'Bloques, CPython y JavaScript ejecutados en tu navegador. Obstáculos, semilla reproducible y telemetría educativa.';$('#map-select').disabled=$('#engine').value==='jvm';$('#seed').disabled=$('#engine').value==='jvm';$('#map-editor-toggle').disabled=$('#engine').value==='jvm';}
