function selectedTanks(selector){return [...$(selector).querySelectorAll('input:checked')].map(i=>project.tanks.find(t=>t.id===i.value)).filter(Boolean).slice(0,9);}
function numeric(selector,min,max){const n=Number($(selector).value);if(!Number.isFinite(n)||n<min||n>max)throw Error('Revisa '+$(selector).closest('label')?.textContent.trim()+': entre '+min+' y '+max+'.');return n;}
function currentMap(){const name=$('#map-select').value;return name==='custom'?project.map:mapPreset(name);}
function log(message){$('#battle-log').textContent=(message+'\n'+$('#battle-log').textContent).slice(0,4000);}
const renderer=new Renderer($('#battle-canvas'));
function snapshotCopy(state){return {tick:state.tick,round:state.round||0,map:state.map||[],robots:state.robots.map(r=>({id:r.id,name:r.name,creator:r.creator||'',colors:r.colors||{},color:r.color,skin:r.skin,x:r.x,y:r.y,heading:r.heading,gun:r.gun,radar:r.radar,energy:r.energy,heat:r.heat,alive:r.alive,metrics:r.metrics?{...r.metrics}:undefined})),bullets:state.bullets.map(b=>({...b})),effects:(state.effects||[]).map(e=>({...e}))};}
function draw(state){lastState=state;if(roomBattle&&room?.session&&Date.now()-lastRoomPush>1000){lastRoomPush=Date.now();room.pushFrame(snapshotCopy(state));}renderer.draw(state,$('#theme').value);$('#battle-tick').textContent=String(state.tick).padStart(4,'0');const roster=$('#battle-roster');roster.replaceChildren();for(const r of state.robots){const item=el('div','roster-item');item.style.setProperty('--tank-color',r.color||COLORS[r.id]);item.append(el('b','',r.name+(r.creator?' · '+r.creator:'')),el('span','',r.alive?Math.max(0,r.energy).toFixed(0)+' EN':'FUERA'));roster.append(item);}const r=state.robots[0];if(!r)return;$('#telemetry').replaceChildren();for(const [label,value] of [['Posición',Math.round(r.x)+', '+Math.round(r.y)],['Rumbo',Math.round(r.heading)+'°'],['Energía',r.energy.toFixed(1)],['Cañón',Math.round(r.gun)+'°'],['Calor',r.heat.toFixed(2)],['Turno',state.tick]]){const row=el('div','stat-row');row.append(el('span','',label),el('b','',value));$('#telemetry').append(row);}if(mission&&r.metrics){const value=Math.min(mission.target,Math.floor(r.metrics[mission.metric]||0));$('#mission-live').textContent=mission.title+' · '+value+'/'+mission.target;if(mission.goal(r)&&!project.completed.includes(mission.id)){project.completed.push(mission.id);project.xp+=mission.xp;save();toast('MISIÓN COMPLETADA · +'+mission.xp+' XP · '+mission.title);beep();}}
}
function beep(){if(!project.settings.sound)return;try{const AC=window.AudioContext||window.webkitAudioContext;const ctx=new AC(),o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);g.gain.setValueAtTime(.04,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.4);o.frequency.setValueAtTime(440,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(880,ctx.currentTime+.25);o.start();o.stop(ctx.currentTime+.4);o.onended=()=>ctx.close();}catch{}}
function finish(result){running=false;paused=false;for(const w of workers.values()){clearTimeout(w.timer);w.worker.terminate();}workers.clear();$('#battle-status').textContent=result.cancelled?'DETENIDO':result.draw?'EMPATE':'PARTIDA TERMINADA';$('#pause-battle').textContent='Pausar';if(!result.cancelled){const winner=result.scores?.find(r=>r.id===result.winner)||(!result.draw?result.scores?.[0]:null);const winningTank=activeTanks[winner?.id];const winnerLabel=winningTank?.name||(battleEngine==='jvm'?winner?.name?.replace(/\*$/,'').split('.').at(-1):winner?.name);$('#winner-name').textContent=result.draw?'EMPATE':winnerLabel||'PARTIDA TERMINADA';$('#winner-description').textContent=result.capped?'Límite de turnos alcanzado. La partida se registra como empate.':result.draw?'Ningún tanque ha conseguido una victoria en el tiempo disponible.':'El código de '+(winnerLabel||'tu tanque')+' ha ganado este encuentro.';if(!result.draw&&winningTank?.creator)$('#winner-description').textContent+=' Creado por '+winningTank.creator+'.';$('#winner-overlay').hidden=!project.settings.celebration||tournamentRunning;beep();log(result.draw?'Resultado: empate.':'Ganador: '+(winner?.name||'—'));if(result.scores?.length)save();}const resolve=battleResolve;battleResolve=null;resolve?.(result);}
function stop(cancelled=true){if(jvmFrame&&battleEngine==='jvm'&&(running||jvmStarting)){jvmFrame.remove();jvmFrame=null;jvmReady=false;jvmInit=null;for(const p of jvmPending.values()){clearTimeout(p.timer);p.reject(Error('JVM detenida.'));}jvmPending.clear();}jvmStarting=false;jvmQueue=[];jvmResult=null;replayFrames=null;if(running||battleResolve)finish({draw:true,cancelled,scores:[],winner:null});battle=null;}
function workerState(r){return {energy:r.energy,x:r.x,y:r.y,heading:r.heading,gun:r.gun,radar:r.radar,heat:r.heat,tick:battle?.tick||0};}
function armWorker(info,id){clearTimeout(info.timer);info.timer=setTimeout(()=>{const r=battle?.robots[id];if(!running||!r?.alive||info.finished)return;if(paused){armWorker(info,id);return;}if(r.pending)return;info.worker.terminate();r.alive=false;info.finished=true;log(r.name+': límite de tiempo sin una nueva orden.');toast(r.name+': programa detenido por no avanzar.');},5000);}
async function prepareWorker(t,id){const worker=new Worker(new URL('./bot-worker.js',import.meta.url));const info={worker,ready:false,request:null,timer:null,finished:false};workers.set(id,info);return new Promise((resolve,reject)=>{info.timer=setTimeout(()=>{worker.terminate();reject(Error(t.name+': el entorno de ejecución no ha cargado a tiempo.'));},90000);worker.onmessage=({data})=>{if(data.type==='ready'){clearTimeout(info.timer);info.ready=true;resolve();}else if(data.type==='command'){clearTimeout(info.timer);if(!battle||!running)return;try{if(!COMMANDS[data.command.type]||['forever','repeat','ifEnergy'].includes(data.command.type))throw Error('Orden no permitida.');battle.queue(id,data.command);info.request=data.id;}catch(e){worker.postMessage({type:'ack',id:data.id,error:e.message});}}else if(data.type==='finished'){info.finished=true;clearTimeout(info.timer);}else if(data.type==='error'){clearTimeout(info.timer);worker.terminate();if(!info.ready)reject(Error(t.name+': '+data.message));else{toast(t.name+': '+data.message);log(t.name+': '+data.message);if(battle?.robots[id]){battle.robots[id].alive=false;battle.robots[id].error=data.message;}}}};worker.onerror=e=>{clearTimeout(info.timer);worker.terminate();if(info.ready){if(battle?.robots[id])battle.robots[id].alive=false;info.finished=true;log(t.name+': '+e.message);toast(t.name+': '+e.message);}else reject(Error(t.name+': '+e.message));};worker.postMessage({type:'start',language:t.language,code:t.code,state:workerState(battle.robots[id])});});}
async function startWeb(tanks,config={}){stop();$('#winner-overlay').hidden=true;mapEditing=false;$('#map-help').hidden=true;const models=tanks.map(t=>({...t,external:['javascript','python'].includes(t.language)}));for(const t of models)if(t.language==='blocks')validateBlocks(t.blocks);battle=new Battle(models,config);battleEngine='web';recording=[];running=true;paused=true;$('#engine-badge').textContent='MOTOR WEB · '+(config.practice?'ENTRENAMIENTO':'COMBATE');$('#battle-status').textContent='CARGANDO ROBOTS';draw(battle.snapshot());try{await Promise.all(models.map((t,id)=>t.external?prepareWorker(t,id):Promise.resolve()));if(!battle||!running)throw Error('Partida detenida.');paused=false;for(const [id,info] of workers)if(info.request===null&&!info.finished)armWorker(info,id);$('#battle-status').textContent='EN COMBATE';return new Promise(resolve=>battleResolve=resolve);}catch(e){stop();throw e;}}
async function initJVM(){if(jvmReady)return;if(jvmInit)return jvmInit;jvmInit=new Promise((resolve,reject)=>{const timer=setTimeout(()=>{jvmInit=null;jvmPending.delete('init');jvmFrame?.remove();jvmFrame=null;reject(Error('La JVM no ha respondido. Comprueba acceso a cjrtnc.leaningtech.com.'));},300000);const request=++jvmSerial;jvmPending.set('init',{resolve:()=>{clearTimeout(timer);jvmPending.delete('init');resolve();},reject:e=>{clearTimeout(timer);jvmPending.delete('init');reject(e);}});jvmFrame=el('iframe');jvmFrame.title='JVM Java de RoboCODEx';jvmFrame.tabIndex=-1;jvmFrame.sandbox='allow-scripts allow-same-origin';jvmFrame.src='jvm.html';$('#jvm-container').replaceChildren(jvmFrame);jvmFrame.onload=()=>jvmFrame.contentWindow.postMessage({channel:'otea-jvm',type:'init',request},location.origin);});return jvmInit;}
function jvmRequest(type,data){return new Promise((resolve,reject)=>{const request=++jvmSerial;const timer=setTimeout(()=>{jvmPending.delete(request);reject(Error('Tiempo de espera de JVM agotado.'));},120000);jvmPending.set(request,{resolve,reject,timer});jvmFrame.contentWindow.postMessage({channel:'otea-jvm',type,request,...data},location.origin);});}
window.addEventListener('message',({data,source,origin})=>{if(!jvmFrame||source!==jvmFrame.contentWindow||origin!==location.origin||data.channel!=='otea-jvm')return;if(data.type==='status'){log(data.message);$('#battle-status').textContent='CARGANDO JVM';diagnostics(data.message);}else if(data.type==='ready'){jvmReady=true;jvmPending.get('init')?.resolve();log('JVM y motor original listos.');}else if(data.type==='compiled'){const p=jvmPending.get(data.request);if(p){clearTimeout(p.timer);jvmPending.delete(data.request);p.resolve(data.results);}}else if(data.type==='frame'&&running&&battleEngine==='jvm'){jvmQueue.push({...data,robots:data.robots.map(r=>{const t=activeTanks.find((t,i)=>javaNames[i]?.split('.').at(-1)===r.name)||activeTanks[r.id];return {...r,name:t?.name||r.name,creator:t?.creator||'',colors:t?tankColors(t):{},skin:t?.skin||'vanguard',color:t?.color||r.color};}),map:[],effects:[]});}else if(data.type==='result'&&running&&battleEngine==='jvm'){let scores=data.scores.map(s=>({...s,id:javaNames.findIndex(n=>s.name.replace(/\*$/,'')===n)}));const tie=data.capped||scores.length===0||(scores.length>1&&scores[0].score===scores[1].score);jvmResult={...data,scores,draw:tie,winner:tie?null:scores[0].id};}else if(data.type==='error'){const message=data.message||'Error JVM';log(message);diagnostics(message,true);const p=jvmPending.get(data.request)||jvmPending.get('init');if(p){clearTimeout(p.timer);p.reject(Error(message));jvmPending.delete(data.request);}else if(running){finish({draw:true,cancelled:true,scores:[],error:message});jvmFrame.remove();jvmFrame=null;jvmReady=false;jvmInit=null;}}});
async function compileJava(tanks){await initJVM();const sources=tanks.map((t,id)=>({id,code:t.language==='blocks'?blocksJava(t.blocks,t.name,t.color):t.code}));const classes=sources.map(s=>(s.code.match(/\bpackage\s+([\w.]+)\s*;/)?.[1]||'')+'.'+(s.code.match(/public\s+(?:final\s+)?class\s+([\w$]+)/)?.[1]||''));if(new Set(classes).size!==classes.length)throw Error('Dos robots tienen la misma clase Java. Cambia el nombre de la clase o el paquete.');const results=await jvmRequest('compile',{sources});const failed=results.filter(r=>!r.result.startsWith('OK:'));if(failed.length)throw Error(failed.map(r=>tanks[r.id].name+'\n'+r.result).join('\n'));return results.map(r=>r.result.slice(3));}
async function startJava(tanks,config={}){stop();mission=null;$('#mission-live').textContent='';jvmStarting=true;battleEngine='jvm';$('#winner-overlay').hidden=true;$('#battle-status').textContent='COMPILANDO JAVA';$('#engine-badge').textContent='JVM JAVA 17 · ROBOCODE 1.11.1';try{const names=await compileJava(tanks);javaNames=names;jvmStarting=false;running=true;paused=false;jvmQueue=[];jvmResult=null;recording=[];$('#battle-status').textContent='EN COMBATE / MOTOR ORIGINAL';jvmFrame.contentWindow.postMessage({channel:'otea-jvm',type:'battle',names:names.join(','),rounds:config.rounds||1,maxTicks:config.maxTicks||2400,cooling:config.cooling||.1,inactivity:450},location.origin);return new Promise(resolve=>battleResolve=resolve);}catch(e){jvmStarting=false;throw e;}}
function advance(forceOne=false){if(!running||paused)return;if(replayFrames){for(let n=0;n<(forceOne?1:Number($('#speed').value));n++){const frame=replayFrames[replayIndex++];if(!frame){finish({draw:true,scores:[],winner:null});replayFrames=null;return;}draw(frame);}return;}if(battleEngine==='jvm'){const steps=forceOne?1:tournamentRunning?80:Number($('#speed').value);for(let i=0;i<steps&&jvmQueue.length;i++){const f=jvmQueue.shift();draw(f);if(recording.length<5000)recording.push(snapshotCopy(f));}if(jvmResult&&!jvmQueue.length){const result=jvmResult;jvmResult=null;finish(result);}return;}if(!battle)return;
 for(let n=0;n<(forceOne?1:tournamentRunning?40:Number($('#speed').value));n++){const waiting=[...workers.entries()].some(([id,w])=>battle.robots[id]?.alive&&!w.finished&&!battle.robots[id].pending&&w.request===null);if(waiting)break;const result=battle.step();for(const [id,w] of workers){const r=battle.robots[id];if(w.request!==null&&!r.pending){const request=w.request;w.request=null;w.worker.postMessage({type:'ack',id:request,state:workerState(r),events:r.events.splice(0)});armWorker(w,id);}}if(battle.tick%2===0&&recording.length<5000)recording.push(snapshotCopy(battle.snapshot()));if(result){draw(battle.snapshot());finish(result);break;}}
 if(running)draw(battle.snapshot());}
let lastAdvance=0;function loop(time){if(time-lastAdvance>1000/30){advance();lastAdvance=time;}requestAnimationFrame(loop);}requestAnimationFrame(loop);
async function runBattle(tanks,engine,config){activeTanks=tanks;spectating=false;if(tanks.length<2&&!config.practice)throw Error('Selecciona al menos dos tanques.');if(tanks.length>8)throw Error('Máximo 8 participantes.');if(tanks.some(t=>engine==='jvm'?!['java','blocks'].includes(t.language):t.language==='java'))throw Error('Hay robots de un motor diferente. Selecciona los compatibles.');return engine==='jvm'?startJava(tanks,config):startWeb(tanks,config);}
function renderMissions(){const container=$('#mission-grid');container.replaceChildren();for(const m of [...MISSIONS,daily()]){const card=el('article','mission-card'+(project.completed.includes(m.id)?' complete':''));card.append(el('span','mission-number',(project.completed.includes(m.id)?'✓ COMPLETADA':'MISIÓN')+' / '+m.concept),el('h2','',m.title),el('p','',m.text),el('code','',m.hint));const b=el('button','outline',project.completed.includes(m.id)?'VOLVER A JUGAR ↗':'ACEPTAR MISIÓN · '+m.xp+' XP ↗');b.onclick=()=>startMission(m);card.append(b);container.append(card);}renderBadges();}
