async function importRobots(files){if(project.tanks.length+files.length>32)throw Error('Máximo 32 robots guardados; 8 por torneo.');for(const f of files){if(f.size>100000)throw Error(f.name+': máximo 100 KB de código.');const code=await f.text(),ext=f.name.split('.').at(-1).toLowerCase(),language={java:'java',py:'python',js:'javascript'}[ext];if(!language)throw Error('Formato no admitido: '+f.name);const name=language==='java'?(code.match(/public\s+(?:final\s+)?class\s+([\w$]+)/)?.[1]||f.name.replace(/\.[^.]+$/,'')):f.name.replace(/\.[^.]+$/,'');project.tanks.push({id:crypto.randomUUID(),name:name.slice(0,40),language,code,blocks:starterBlocks(),color:COLORS[project.tanks.length%COLORS.length],skin:'vanguard'});}save();renderEditor();renderParticipants();renderTournamentParticipants();toast(files.length+' robots importados. Se validarán antes de competir.');}
