$('#engine').onchange=()=>{stop();renderParticipants();};$('#start-battle').onclick=guard(async()=>{mission=null;$('#mission-live').textContent='';await runBattle(selectedTanks('#participants'),$('#engine').value,{seed:numeric('#seed',0,4294967295),map:$('#engine').value==='jvm'?[]:currentMap(),maxTicks:numeric('#ticks',50,20000),cooling:numeric('#cooling',.01,1)});});$('#pause-battle').onclick=()=>{paused=!paused;$('#pause-battle').textContent=paused?'Continuar':'Pausar';$('#battle-status').textContent=paused?'EN PAUSA':'EN COMBATE';};$('#step-battle').onclick=()=>{if(!running)return;paused=false;advance(true);paused=true;$('#pause-battle').textContent='Continuar';};$('#stop-battle').onclick=()=>{if(tournamentRunning)tournamentCancel=true;stop();};$('#winner-close').onclick=()=>$('#winner-overlay').hidden=true;$('#random-seed').onclick=()=>$('#seed').value=crypto.getRandomValues(new Uint32Array(1))[0];$('#theme').onchange=()=>{if(lastState)draw(lastState);save();};$('#map-select').onchange=()=>{if(!running)draw({...lastState,map:currentMap()});save();};$('#map-editor-toggle').onclick=()=>{stop();mapEditing=!mapEditing;$('#map-help').hidden=!mapEditing;$('#map-select').value='custom';draw({tick:0,robots:[],bullets:[],effects:[],map:project.map});};$('#battle-canvas').onclick=e=>{if(!mapEditing)return;const rect=e.target.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*800,y=800-(e.clientY-rect.top)/rect.height*800;const index=project.map.findIndex(o=>x>=o.x&&x<=o.x+o.w&&y>=o.y&&y<=o.y+o.h);if(index>=0)project.map.splice(index,1);else if(project.map.length<40)project.map.push({x:clamp(Math.round((x-40)/40)*40,40,680),y:clamp(Math.round((y-40)/40)*40,40,680),w:80,h:80});save();draw({tick:0,robots:[],bullets:[],effects:[],map:project.map});};$('#export-replay').onclick=()=>{if(!recording.length)return toast('Ejecuta una partida para guardar su repetición.');download('RoboCODEx-repeticion.json',JSON.stringify({version:1,type:'replay',engine:battleEngine,frames:recording}));};$('#replay-file').onchange=guard(async e=>{const f=e.target.files[0];if(!f)return;if(f.size>15000000)throw Error('Repetición demasiado grande.');const replay=JSON.parse(await f.text());if(replay.type!=='replay'||!Array.isArray(replay.frames)||replay.frames.length>5000||!replay.frames.every(s=>Array.isArray(s.robots)&&s.robots.length<=8&&s.robots.every(r=>['x','y','heading','gun','radar','energy','heat','id'].every(k=>Number.isFinite(r[k]))&&typeof r.name==='string')&&Array.isArray(s.bullets)&&s.bullets.length<1000))throw Error('Repetición no válida.');stop();replayFrames=replay.frames;replayIndex=0;running=true;paused=false;$('#winner-overlay').hidden=true;$('#battle-status').textContent='REPETICIÓN';e.target.value='';});
$('#daily-start').onclick=()=>startMission(daily());$('#tournament-engine').onchange=renderTournamentParticipants;$('#start-tournament').onclick=guard(startTournament);$('#cancel-tournament').onclick=()=>{tournamentCancel=true;stop();};$('#export-tournament').onclick=()=>{if(!standings.length)return toast('Todavía no hay resultados.');const escape=s=>'"'+String(s).replaceAll('"','""')+'"';const safe=s=>/^[=+@-]/.test(String(s))?"'"+s:s;const rows=[['Tanque','Creador','Puntos','Victorias','Empates','Derrotas','Buchholz','Combate'],...standings.map(s=>[safe(s.name),safe(s.creator||''),s.points,s.wins,s.draws,s.losses,s.buchholz,s.combat])];download('RoboCODEx-torneo.csv','\uFEFF'+rows.map(row=>row.map(escape).join(';')).join('\r\n'),'text/csv;charset=utf-8');};
$('#settings-open').onclick=()=>$('#settings').showModal();$('#settings-close').onclick=()=>$('#settings').close();$('#fx').onchange=()=>{project.settings.effects=Number($('#fx').value);settingsApply();save();};for(const k of ['ambient','trails','radar','celebration','sound','large','contrast','grid','health','creators'])$('#'+k+'-toggle').onchange=()=>{project.settings[k]=$('#'+k+'-toggle').checked;settingsApply();save();};$('#calm-mode').onclick=()=>{Object.assign(project.settings,{effects:0,ambient:false,trails:false,radar:false,celebration:false,sound:false});settingsApply();save();toast('Modo calma activado.');};$('#export-project').onclick=()=>download('RoboCODEx-proyecto.json',JSON.stringify(project,null,2));$('#project-file').onchange=guard(async e=>{const f=e.target.files[0];if(!f)return;if(f.size>4000000)throw Error('Máximo 4 MB de proyecto.');const imported=validateProject(JSON.parse(await f.text()));stop();project=imported;project.completed=project.completed||[];project.xp=project.xp||0;project.settings={...defaultProject().settings,...project.settings};selected=project.tanks[0].id;restoreUI();settingsApply();renderEditor();save();toast('Proyecto restaurado.');e.target.value='';});
