const roomConfig=()=>({engine:$('#tournament-engine').value,map:$('#tournament-engine').value==='jvm'?'classic':$('#tournament-map').value,theme:$('#tournament-theme').value,maxTicks:numeric('#simple-ticks',100,10000),seed:Number($('#seed').value)||137,autoStart:Number($('#room-auto').value)});
function roomTanksRender(){const select=$('#room-tank'),old=select.value;select.replaceChildren();for(const t of project.tanks){const compatible=(roomState?.config.engine||$('#tournament-engine').value)==='jvm'?['java','blocks'].includes(t.language):t.language!=='java';if(!compatible)continue;const o=el('option','',t.name+(t.creator?' · '+t.creator:''));o.value=t.id;select.append(o);}if([...select.options].some(o=>o.value===old))select.value=old;}
function roomRender(data){roomState=data;$('#room-live').hidden=false;$('#room-label').textContent=data.name;$('#room-name').value=data.name;$('#room-host').hidden=!data.host;$('#room-create').disabled=true;$('#room-join').disabled=true;$('#room-name').disabled=true;$('#room-password').disabled=true;const statuses={waiting:'INSCRIPCIÓN ABIERTA',running:'BATALLA EN MARCHA',finished:'BATALLA COMPLETADA',cancelled:'BATALLA DETENIDA'};$('#room-status').textContent=statuses[data.status]+' · '+data.participants.length+'/8 tanques';const waiting=data.status==='waiting';$('#room-submit').disabled=!waiting;$('#room-start').disabled=!waiting||data.participants.length<2||roomBusy;$('#room-add-bots').disabled=!waiting;$('#room-reset').disabled=waiting||data.status==='running';$('#room-stop').disabled=data.status!=='running';for(const id of ['tournament-engine','tournament-map','tournament-theme','simple-ticks','room-auto'])$('#'+id).disabled=!data.host||!waiting||data.config.engine==='jvm'&&id==='tournament-map';$('#tournament-engine').value=data.config.engine;$('#tournament-map').value=data.config.map;$('#tournament-theme').value=data.config.theme;$('#simple-ticks').value=data.config.maxTicks;$('#room-auto').value=data.config.autoStart;$('#room-roster').replaceChildren();for(const p of data.participants){const row=el('div','room-participant');row.append(el('span','',p.name+(p.creator?' · '+p.creator:'')),el('small','',p.language));if(data.host&&waiting){const b=el('button','','×');b.setAttribute('aria-label','Retirar '+p.name);b.onclick=guard(()=>room.action('remove',{id:p.id}));row.append(b);}$('#room-roster').append(row);}roomTanksRender();
 if(!data.host){spectating=true;activeTanks=[];for(const id of ['start-battle','pause-battle','step-battle','stop-battle','test-tank','simple-tournament','start-tournament'])$('#'+id).disabled=true;if(data.frame){draw(data.frame);$('#battle-status').textContent=statuses[data.status]+' · '+data.name;}if(data.result&&!data.result.cancelled){const winner=data.participants.find(p=>p.tank?.id===data.result.winnerTankId||p.id===data.result.winnerMemberId);$('#winner-name').textContent=data.result.draw?'EMPATE':winner?.name||data.result.winnerName||'FIN DE LA PARTIDA';$('#winner-description').textContent=data.result.winnerCreator?'Creado por '+data.result.winnerCreator: data.result.draw?'Límite de turnos o empate.':'La batalla de la sala ha terminado.';$('#winner-overlay').hidden=!project.settings.celebration;showSingleStandings(data.participants.map(p=>({name:p.name,creator:p.creator})),data.result,data.name);}}
 if(data.host&&waiting&&data.config.autoStart&&data.participants.length>=data.config.autoStart&&!roomBusy)void guard(startRoomBattle)();
}
function showSingleStandings(tanks,result,name){standings=tanks.map((t,id)=>({id,name:t.name,creator:t.creator||'',points:result.cancelled?0:result.draw?1:result.winner===id?3:0,wins:!result.draw&&result.winner===id?1:0,draws:result.draw&&!result.cancelled?1:0,losses:!result.draw&&result.winner!==id?1:0,buchholz:0,combat:Math.round(result.scores?.find(s=>s.id===id)?.score||0),opponents:[]}));fixtures=[{a:tanks.map(t=>t.name).join(' · '),b:'batalla conjunta',result:result.cancelled?'Detenida':result.draw?'Empate':(tanks[result.winner]?.name||result.winnerName||'Tanque')+' gana',round:'Una partida · '+(result.ticks||lastState?.tick||0)+' turnos'}];currentTournament={name,engine:battleEngine,pairing:'melee'};$('#league-title').textContent=name;standingsRender();}
async function startSingle(tanks,c,name){for(const t of tanks){validateTank(t);if(t.language==='blocks')validateBlocks(t.blocks);}if(tournamentRunning||running||jvmStarting)throw Error('Detén la partida actual antes de iniciar otra batalla.');mission=null;$('#mission-live').textContent='';$('#theme').value=c.theme;$('#map-select').value=c.map;$('#engine').value=c.engine;go('arena');renderParticipants();const result=await runBattle(tanks,c.engine,{seed:c.seed,maxTicks:c.maxTicks,map:c.engine==='jvm'?[]:mapPreset(c.map),cooling:Number($('#cooling').value)||.1});showSingleStandings(tanks,result,name);$('#tournament-status').textContent=result.cancelled?'Batalla detenida.':'BATALLA CONJUNTA COMPLETADA · '+tanks.length+' participantes';return result;}
async function startRoomBattle(){if(roomBusy||!roomState?.host||roomState.status!=='waiting')return;roomBusy=true;try{if(running||jvmStarting||tournamentRunning)throw Error('Detén la partida actual antes de iniciar la sala.');const data=await room.action('start');const tanks=data.participants.map(p=>p.tank),members=data.participants.map(p=>p.id);for(const t of tanks){validateTank(t);if(t.language==='blocks')validateBlocks(t.blocks);}roomBattle=true;lastRoomPush=0;const result=await startSingle(tanks,data.config,data.name);roomBattle=false;if(lastState&&running===false)await room.action('frame',{frame:snapshotCopy(lastState)});const winning=tanks[result.winner];await room.action('result',{result:{...result,winnerTankId:winning?.id||null,winnerMemberId:members[result.winner]||null,winnerName:winning?.name||'',winnerCreator:winning?.creator||''}});}catch(e){roomBattle=false;if(roomState?.status==='running')try{await room.action('result',{result:{cancelled:true,draw:true,winner:null,scores:[]}});}catch{}throw e;}finally{roomBusy=false;}}
room=new RoomClient(roomRender,e=>{$('#room-status').textContent=e.message;if([401,410].includes(e.status))roomCleanup();});
function roomCleanup(){room.forget();roomState=null;spectating=false;$('#room-live').hidden=true;for(const id of ['room-create','room-join','room-name','room-password','start-battle','pause-battle','step-battle','stop-battle','test-tank','simple-tournament','start-tournament','tournament-engine','tournament-map','tournament-theme','simple-ticks','room-auto'])$('#'+id).disabled=false;renderTournamentParticipants();$('#room-status').textContent='Has salido de la sala.';}
for(const [id,action] of [['room-create','create'],['room-join','join']])$('#'+id).onclick=guard(async()=>{if(running||jvmStarting||tournamentRunning)throw Error('Detén la partida actual antes de entrar en una sala.');const password=$('#room-password').value;try{await room.enter(action,$('#room-name').value,password,roomConfig());}finally{$('#room-password').value='';}});
$('#room-submit').onclick=guard(async()=>{const t=project.tanks.find(t=>t.id===$('#room-tank').value);if(!t)throw Error('Construye un tanque compatible primero.');validateTank(t);if(t.language==='blocks')validateBlocks(t.blocks);await room.action('submit',{tank:{...t,creator:t.creator||''}});toast('Tanque inscrito en la sala.');});
$('#room-add-bots').onclick=guard(async()=>{const list=selectedTanks('#tournament-participants');if(!list.length)throw Error('Selecciona los robots del hangar que quieres añadir.');for(const t of list){validateTank(t);if(t.language==='blocks')validateBlocks(t.blocks);}if(roomState.participants.length+list.length>8)throw Error('La sala admite ocho tanques en total.');roomBusy=true;try{for(const t of list)await room.action('submit',{tank:{...t,creator:t.creator||''},automatic:true});}finally{roomBusy=false;roomRender(roomState);}});
$('#room-start').onclick=guard(startRoomBattle);$('#room-stop').onclick=guard(async()=>{if(roomBattle){stop();}else await room.action('result',{result:{cancelled:true,draw:true,winner:null,scores:[]}});});$('#room-watch').onclick=()=>go('arena');$('#room-reset').onclick=guard(()=>room.action('reset'));
$('#room-leave').onclick=guard(async()=>{if(roomState?.host){if(roomBusy)throw Error('Detén la batalla antes de cerrar la sala.');await room.action('close');}else await room.action('leave');roomCleanup();});
$('#simple-tournament').onclick=guard(()=>{if(room?.session)throw Error('En una sala usa INICIAR BATALLA DE SALA.');return startSingle(selectedTanks('#tournament-participants'),roomConfig(),$('#tournament-name').value||'Copa OTEA');});
for(const id of ['tournament-engine','tournament-map','tournament-theme','simple-ticks','room-auto'])$('#'+id).addEventListener('change',guard(async()=>{if(id==='tournament-engine'){$('#tournament-map').disabled=$('#'+id).value==='jvm';if($('#'+id).value==='jvm')$('#tournament-map').value='classic';}if(room?.session&&roomState?.host)await room.action('config',{config:roomConfig()});}));
